local module = {}
module.__index = module

function module.new(
	eventBus: IEventBus,
	protocolManager: IProtocolManager,
	env: IHostingEnvironment,
	activatorUtilities: IActivatorUtilities,
	playerScopeService: IPlayerScopeService
)
	local self = setmetatable({}, module)
	self.EventBus = eventBus
	self.ProtocolManager = protocolManager
	self.IsServer = env:IsServer()
	self.ActivatorUtilities = activatorUtilities
	self.PlayerScopeService = playerScopeService
	return self
end

function module:_createProtocolImplemention(protocol: string, player: Player, ...)
	-- 获取协议实现
	local implemention = self.ProtocolManager:GetProtocolImplemention(protocol)
	if not implemention then
		warn("protocol implemention not found", protocol)
		return
	end

	-- 获取玩家 scope
	local scope = self.PlayerScopeService.GetPlayerScope(player)

	-- 创建Protocol实例，由于实例是一个 function, 所以不需要针对实例进行操作
	local activatorUtilities = self.ActivatorUtilities :: IActivatorUtilities
	return activatorUtilities.CreateInstance(scope._serviceProvider, implemention, ...)
end

function module:_onReceiveProtocol(protocol, ...)
	local args = { ... }
	local player = game.Players.LocalPlayer
	self:_createProtocolImplemention(protocol, player, args)
end

function module:_onInvokePlayerProtocol(player: Player, protocol, ...)
	local response = self:_createProtocolImplemention(protocol, player, ...)
	return response
end

function module:_onReceivePlayerProtocol(player: Player, protocol: string, ...)
	self:_createProtocolImplemention(protocol, player, ...)
end

function module:_registerServerProtocol()
	local eventBus: IEventBus = self.EventBus
	local connection1 = eventBus.OnInvokeC2S(function(...)
		return self:_onInvokePlayerProtocol(...)
	end)
	local connection2 = eventBus.ConnectC2S(function(...)
		self:_onReceivePlayerProtocol(...)
	end)
	self._connections = { connection1, connection2 }
end

function module:_registerClientProtocol()
	local eventBus: IEventBus = self.EventBus
	local connection = eventBus.ConnectS2C(function(...)
		self:_onReceiveProtocol(...)
	end)
	self._connections = { connection }
end

function module:Start()
	if self._connections then
		return
	end

	if self.IsServer then
		self:_registerServerProtocol()
	else
		self:_registerClientProtocol()
	end
end

function module:Stop()
	for _, connection in self._connections do
		connection:Disconnect()
	end
	self._connections = nil
end

return module
